H.background();
const Wk = P.work;
const time = Math.max(0.1, P.time);
const Pavg = Wk / time;
const phase = (t * 0.5) % 1;
const wDone = Wk * phase;
const tNow = time * phase;
const bx = 60, by = 110, bw = H.W - 120, bh = 26;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 2, radius: 4 });
H.rect(bx, by, bw * phase, bh, { fill: H.colors.accent, radius: 4 });
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: 0, yMax: Math.max(50, Pavg * 1.5 + 10) });
v.grid(); v.axes();
v.fn(tt => Wk / Math.max(0.1, tt), { color: H.colors.violet, width: 3 });
v.dot(time, Pavg, { r: 7, fill: H.colors.warn });
const refV = 2;
const Fequiv = Pavg / refV;
H.text("Power: P = W / t = F v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Power is the RATE of doing work (watts = J/s)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("W = " + wDone.toFixed(0) + " / " + Wk.toFixed(0) + " J   t = " + tNow.toFixed(2) + " s", 24, 78, { color: H.colors.sub, size: 13 });
H.text("P = " + Pavg.toFixed(1) + " W   (= F v: F = " + Fequiv.toFixed(1) + " N at v = " + refV + " m/s)", 24, 96, { color: H.colors.good, size: 13 });
